#!/usr/bin/env python3
import base64,sys,os
D=os.path.dirname(os.path.abspath(__file__)); IDX=os.path.join(D,'index.html')
ACCT=base64.b64decode("").decode()
NAVJS=base64.b64decode("").decode()
NAV_HTML=base64.b64decode("").decode()
CSS=base64.b64decode("").decode()
h=open(IDX,encoding='utf-8').read()
if 'switchAcctTab' in h or 'toggleSiteMenu' in h:
    print('ABORT: already applied'); sys.exit(2)
# 1) replace accountArea function region with tabbed version (+switchAcctTab +acctTab)
i0=h.find('function accountArea(){')
i1=h.find('function mbtiBlurb(t){')
if i0<0 or i1<0 or i1<i0: raise SystemExit('accountArea region not found')
h=h[:i0]+ACCT+'\n'+h[i1:]
# 2) drop standalone settingsCard() from studio
old='$'+'{settingsCard()}\n  $'+'{accountArea()}'
if h.find(old)<0 or h.find(old)!=h.rfind(old): raise SystemExit('settingsCard/accountArea render anchor bad')
h=h.replace(old,'$'+'{accountArea()}',1)
# 3) replace <nav>...</nav>
n0=h.find('<nav>'); n1=h.find('</nav>')
if n0<0 or n1<0: raise SystemExit('nav not found')
n1+=len('</nav>')
h=h[:n0]+NAV_HTML+h[n1:]
# 4) append nav JS before last </script>
sc=h.rfind('</script>'); h=h[:sc]+NAVJS+'\n'+h[sc:]
# 5) CSS before </style>
sty=h.find('</style>'); h=h[:sty]+CSS+h[sty:]
open(IDX,'w',encoding='utf-8',newline='\r\n').write(h)
print('OK tabs+nav; switchAcctTab=',h.count('switchAcctTab'),'toggleSiteMenu=',h.count('toggleSiteMenu'),'siteMenu=',h.count('id="siteMenu"'),'accountArea=',h.count('function accountArea'))
